// Live NAV page — daily NAV for the five portfolios since inception, rendered from data/live_nav.js
// (generated by Src/fund_nav.py -> Src/pc_fund_live_page.py). Nothing here is hand-typed data:
// identities, colours, fees and dealing rules are all published from the registry.
//
// Layout: the page is a PRODUCT page for one selected portfolio (hero, performance, portfolio,
// attribution), followed by the RANGE — all five side by side. One selection drives every panel,
// is carried in ?p=<key> and shared with the rest of the platform through the same localStorage key
// portfolio-select.js uses, so choosing SAA here and clicking Holdings lands on SAA's holdings.

/* global Plotly */
(function () {
  const D = window.LIVE_NAV;
  const el = (id) => document.getElementById(id);

  // Mobile navigation. app.js wires this on every other page; this page does not load app.js, so the
  // hamburger did nothing on a phone. Wired first, so it works even if the payload is missing.
  (function initNav() {
    const btn = document.querySelector(".navtoggle"), nav = document.querySelector(".appnav");
    if (!btn || !nav) return;
    btn.addEventListener("click", (e) => { e.stopPropagation(); nav.classList.toggle("open"); });
    document.addEventListener("click", (e) => {
      if (nav.classList.contains("open") && !nav.contains(e.target) && !btn.contains(e.target))
        nav.classList.remove("open");
    });
  })();

  if (!D) { el("appbar-status").textContent = "live_nav.js data missing"; return; }

  // One palette for the page. Gain/loss are polarity, the accent is magnitude, slate is reference;
  // identity colours (from the registry) mark which portfolio and nothing else.
  const P = { ink: "#0f172a", muted: "#64748b", grid: "#eef2f7", axis: "#e2e8f0",
    gain: "#059669", loss: "#dc2626", gainQuiet: "#9fd3c0", lossQuiet: "#f3b1ab",
    accent: "#2563eb", ref: "#94a3b8", refLight: "#cbd5e1", zero: "#94a3b8" };
  const INK = P.ink, MUTED = P.muted, GRID = P.grid, AXIS = P.axis;
  // Magnitude (a weight, a share, a month's return) is drawn in one neutral platform hue. Identity
  // colours mark WHICH portfolio — swatches, lines — and are not reused as bar fills: Alpha's registry
  // colour is the platform's loss red, so its weights and a rising month read as losses.
  const MAG = P.accent;
  const FONT = { family: "-apple-system, BlinkMacSystemFont, Segoe UI, Roboto, sans-serif", size: 11, color: "#64748b" };
  const BASE = { font: FONT, margin: { l: 46, r: 14, t: 8, b: 30 }, paper_bgcolor: "transparent",
    plot_bgcolor: "transparent", separators: ".,",
    // Light tooltip on purpose: a dark box leaves the series name outside it in the series colour,
    // which is unreadable for the pale identity colours.
    hoverlabel: { bgcolor: "#ffffff", bordercolor: "#cbd5e1", font: { size: 12, color: "#0f172a" }, align: "left" },
    xaxis: { gridcolor: GRID, zeroline: false, linecolor: AXIS, ticks: "", tickfont: { size: 10 } },
    yaxis: { gridcolor: GRID, zeroline: false, linecolor: AXIS, ticks: "", tickfont: { size: 10 } } };
  const CFG = { displayModeBar: false, responsive: true };

  // Plotly MUTATES the layout object it is handed — it writes `type`, `range` and `autorange` back
  // onto the axis objects. A shared axis object once stamped type:"date" onto the contribution bars
  // and rendered their points-of-NAV axis as timestamps around Dec 31 1969. Always hand Plotly
  // freshly built axes. Same helper as portfolios.js, for the same reason.
  const L = (extra) => {
    const e = extra || {};
    return Object.assign({}, BASE, e, {
      xaxis: Object.assign({}, BASE.xaxis, e.xaxis || {}),
      yaxis: Object.assign({}, BASE.yaxis, e.yaxis || {}),
    });
  };

  const FUNDS = D.fund_list, BENCH = D.bench_list;
  const T = D.track, F0 = D.facts[D.fund_list[0]];
  // Identity colours come from the payload, which publishes fund_registry. Never re-type them here:
  // the hand-copied map had drifted until Certain used SAA's colour and SAA used DAA's.
  const COLOR = Object.assign(
    {}, D.bench_colors || {},
    Object.fromEntries(FUNDS.map((f) => [f, (D.facts[f] || {}).color || "#3083b4"])));
  const pct = (x, d = 2) => (x < 0 ? "−" : "") + Math.abs(x * 100).toFixed(d) + "%";
  const pp = (x, d = 2) => (x >= 0 ? "+" : "−") + Math.abs(100 * x).toFixed(d) + "%";
  const sgn = (v, d = 2) => (v >= 0 ? "+" : "−") + Math.abs(v).toFixed(d);
  // A value that rounds to zero prints as 0.00, never as a signed "−0.00".
  const n2 = (v) => v === null || v === undefined ? "—" : (v <= -0.005 ? "−" : "") + Math.abs(v).toFixed(2);
  const cls = (x) => (x < 0 ? "neg" : "pos");
  const fmtD = (s) => new Date(s + "T00:00:00").toLocaleDateString("en-GB",
    { day: "numeric", month: "short", year: "numeric" });
  const lab = (k) => (D.labels && D.labels[k]) ? D.labels[k] : k;

  // ---------- selection: one portfolio, shared with the platform ----------
  const KEY = "summer.portfolio";
  const keyOf = (f) => f.toLowerCase();
  const byKey = Object.fromEntries(FUNDS.map((f) => [keyOf(f), f]));
  let fund = (function pick() {
    const q = (new URLSearchParams(location.search).get("p") || "").toLowerCase();
    if (byKey[q]) return byKey[q];
    try { const s = localStorage.getItem(KEY); if (s && byKey[s]) return byKey[s]; } catch (e) { /* private window */ }
    return FUNDS.includes("SAA") ? "SAA" : FUNDS[0];
  })();

  // Carry the choice into the deep pages, exactly as portfolio-select.js does on those pages.
  const DEEP = new Set(["index.html", "construction.html", "holdings.html", "performance.html",
    "attribution.html", "risk.html", "stress.html", "montecarlo.html"]);
  function syncNav() {
    document.querySelectorAll(".appnav a").forEach((a) => {
      const href = a.getAttribute("href");
      if (!href || !DEEP.has(href.split("?")[0])) return;
      a.setAttribute("href", `${href.split("?")[0]}?p=${keyOf(fund)}`);
    });
  }

  function select(f) {
    if (!FUNDS.includes(f) || f === fund) return;
    fund = f;
    try { localStorage.setItem(KEY, keyOf(f)); } catch (e) { /* ignore */ }
    try {
      const u = new URL(location.href); u.searchParams.set("p", keyOf(f));
      history.replaceState(null, "", u.toString());
    } catch (e) { /* file:// in some browsers */ }
    renderProduct();
    renderRangeSelection();
  }

  // ---------- helpers shared by the charts ----------
  // The date axis skips weekends and market holidays. Without this every Friday-to-Monday is drawn
  // as a straight ramp across two empty days, which is most of what made the NAV line look rough.
  const RANGEBREAKS = (function () {
    const have = new Set(D.dates), miss = [];
    const d = new Date(D.dates[0] + "T00:00:00"), end = new Date(D.dates[D.dates.length - 1] + "T00:00:00");
    for (; d <= end; d.setDate(d.getDate() + 1)) {
      const wd = d.getDay(), iso = d.toISOString().slice(0, 10);
      if (wd !== 0 && wd !== 6 && !have.has(iso)) miss.push(iso);
    }
    return [{ bounds: ["sat", "mon"] }].concat(miss.length ? [{ values: miss }] : []);
  })();
  const narrow = (id) => { const n = el(id); return !!n && n.offsetWidth > 0 && n.offsetWidth < 560; };
  const DATE_AXIS = (d, id) => ({ nticks: id && narrow(id) ? 4 : 8, tickangle: 0, type: "date", range: d ? [d[0], d[d.length - 1]] : undefined, showgrid: false, linecolor: AXIS, ticks: "outside",
    ticklen: 3, tickcolor: AXIS, tickfont: { size: 10 }, rangebreaks: RANGEBREAKS,
    tickformat: "%-d %b", hoverformat: "%a %-d %b %Y" });

  // A readable price axis: a round step that gives four to six gridlines, and padding so a 0.2% day
  // is not stretched into a 20px spike.
  function niceAxis(vals, padFrac = 0.18) {
    const lo = Math.min(...vals), hi = Math.max(...vals), span = (hi - lo) || Math.abs(hi) * 0.01 || 1;
    const a = lo - span * padFrac, b = hi + span * padFrac;
    const raw = (b - a) / 5, mag = Math.pow(10, Math.floor(Math.log10(raw)));
    const step = [1, 2, 2.5, 5, 10].map((m) => m * mag).find((s) => s >= raw) || 10 * mag;
    return { range: [a, b], dtick: step };
  }
  const tickFmtFor = (dt) => (dt >= 1 ? ".0f" : dt >= 0.1 ? ".1f" : ".2f");

  // Spread end-of-line labels so they never sit on top of each other.
  function declutter(items, span, gapFrac = 0.06) {
    const gap = span * gapFrac, s = items.slice().sort((a, b) => a.y - b.y);
    for (let i = 1; i < s.length; i++) if (s[i].y - s[i - 1].ly < gap) s[i].ly = s[i - 1].ly + gap;
    s.forEach((it) => { if (it.ly === undefined) it.ly = it.y; });
    return items;
  }
  function prep(items) { items.forEach((it) => { it.ly = it.y; }); return items; }

  function periodStart(months) {
    if (!months) return 0;
    const cut = new Date(D.dates[D.dates.length - 1] + "T00:00:00");
    cut.setMonth(cut.getMonth() - months);
    return Math.max(0, D.dates.findIndex((d) => new Date(d + "T00:00:00") >= cut));
  }
  const ser = (n) => (D.series && D.series[n]) || (D.ref_series && D.ref_series[n]);

  // ================================================================================================
  // PRODUCT
  // ================================================================================================

  // ---------- switcher ----------
  // The five portfolios as tabs: name, NAV, move on the day. This is navigation, not a KPI strip — it
  // carries no launch date or record length, and it is in the range's own order, never ranked.
  function switcher() {
    el("lv-switch").innerHTML = `<div class="lv-switch-in">` + FUNDS.map((f) => {
      const st = D.stats[f], dy = D.day[f], x = D.facts[f];
      return `<button class="lv-tab${f === fund ? " sel" : ""}" data-f="${f}" style="--pc:${COLOR[f]}"
          aria-pressed="${f === fund}">
        <span class="lv-tab-name"><i></i>${f}</span>
        <span class="lv-tab-role">${x.managed === "active" ? "active" : "policy"} · ${x.horizon}</span>
        <span class="lv-tab-nav">${st.nav.toFixed(2)}<em class="${cls(dy.chg)}">${pp(dy.chg)}</em></span>
      </button>`;
    }).join("") + `<div class="lv-switch-asof">NAV per unit · priced ${fmtD(D.asof)}</div></div>`;
    el("lv-switch").querySelectorAll(".lv-tab").forEach((b) => { b.onclick = () => select(b.dataset.f); });
  }

  // ---------- hero ----------
  function spark(name) {
    const y = D.series[name], n = y.length, lo = Math.min(...y, D.nav0), hi = Math.max(...y, D.nav0);
    const rng = hi - lo || 1, W = 100, H = 30;
    const pts = y.map((v, i) => `${(i / (n - 1) * W).toFixed(2)},${(H - (v - lo) / rng * H).toFixed(2)}`);
    const base = (H - (D.nav0 - lo) / rng * H).toFixed(2);
    return `<svg viewBox="0 0 ${W} ${H}" preserveAspectRatio="none" aria-hidden="true">
      <line x1="0" x2="${W}" y1="${base}" y2="${base}" stroke="rgba(255,255,255,.35)" stroke-width="1"
        stroke-dasharray="3 3" vector-effect="non-scaling-stroke"/>
      <polyline points="${pts.join(" ")}" fill="none" stroke="#fff" stroke-width="1.6"
        vector-effect="non-scaling-stroke" stroke-linejoin="round"/></svg>`;
  }

  function hero() {
    const f = fund, st = D.stats[f], dy = D.day[f], x = D.facts[f], id = D.funds[f] || {};
    const ref = D.ref_stats[f], sr = D.series[f];
    const hs = (v, l, c) => `<div class="hstat"><div class="hstat-v ${c || ""}">${v}</div><div class="hstat-l">${l}</div></div>`;
    const k = keyOf(f);
    el("lv-hero").style.setProperty("--pc", COLOR[f]);
    el("lv-hero").innerHTML = `
      <div class="lv-hero-main">
        <div class="hero-eyebrow">Live portfolio · multi-asset · ${x.currency} · accumulating</div>
        <div class="lv-title"><span class="lv-swatch"></span><h2>${f}</h2>
          <span class="lv-kind ${x.managed === "active" ? "act" : "sta"}">${
            x.managed === "active" ? "actively run" : "policy weights"}</span></div>
        <div class="lv-role">${x.role}</div>
        <p class="hero-thesis">${id.purpose || ""}</p>
        <p class="lv-identity">${id.identity || ""}</p>
        <div class="lv-deep"><span>Go deeper on ${f}</span>
          <a href="index.html?p=${k}">Overview</a><a href="construction.html?p=${k}">Construction</a>
          <a href="holdings.html?p=${k}">Holdings</a><a href="performance.html?p=${k}">Backtest</a>
          <a href="risk.html?p=${k}">Risk</a><a href="stress.html?p=${k}">Stress</a></div>
      </div>
      <div class="lv-hero-nav">
        <div class="lv-nav-l">NAV per unit · ${fmtD(D.asof)}</div>
        <div class="lv-nav-row">
          <div class="lv-nav-v">${st.nav.toFixed(2)}<small>${x.currency}</small></div>
          <div class="lv-nav-d ${cls(dy.chg)}">${dy.pts >= 0 ? "▲" : "▼"} ${sgn(dy.pts)}
            <span>(${pp(dy.chg)})</span><em>on the day</em></div>
        </div>
        <div class="lv-hero-spark">${spark(f)}<div class="lv-spark-cap"><span>${fmtD(D.inception)}</span>
          <span>dashed: launch at ${D.nav0.toFixed(2)}</span></div></div>
        <div class="lv-hstats">
          ${hs(pp(st.ret), "since launch · net", cls(st.ret))}
          ${hs(pp(ref.excess), "vs " + ref.name, cls(ref.excess))}
          ${hs(pct(dy.dd, 1), "from its high", dy.dd < -0.0001 ? "neg" : "")}
          ${hs(Math.min(...sr).toFixed(2) + "–" + Math.max(...sr).toFixed(2), "range since launch")}
        </div>
      </div>`;
    document.title = `${f} — Live NAV — Multi-Asset Portfolio`;
  }

  // Key facts: the terms a factsheet leads with, for THIS portfolio. The all-five terms table is
  // kept in the range section.
  function keyFacts() {
    const f = fund, x = D.facts[f], C = (D.chars || {})[f] || {};
    const it = (l, v, h) => `<div class="lv-fact"><span>${l}</span><b>${v}</b>${h ? `<em>${h}</em>` : ""}</div>`;
    el("lv-facts").innerHTML = [
      it("Launched", fmtD(D.inception), "at " + D.nav0.toFixed(2) + " per unit"),
      it("Reference", x.reference, "what it is measured against"),
      it("Horizon", x.horizon),
      it("Management", x.managed === "active" ? "Actively run" : "Policy weights", x.dealing),
      it("Ongoing charge", x.fee_bps + "bp a year", x.dealing_bps + "bp per side dealt"),
      it("Holdings", Object.keys(D.holdings[f]).length, "no vehicle above " + (x.vehicle_cap * 100).toFixed(0) + "%*"),
      C.dd_cap !== undefined && C.dd_cap !== null
        ? it("Drawdown cap", pct(C.dd_cap, 1) + (C.dd_loosened ? "*" : ""), "construction constraint") : "",
      it("Distribution", "Accumulating", "income reinvested in the NAV"),
    ].join("");
  }

  // ---------- NAV chart ----------
  const PERIODS = [["1M", 1], ["3M", 3], ["6M", 6], ["1Y", 12], ["SI", null]];
  const MODES = [["nav", "NAV"], ["ref", "Against its reference"], ["dd", "From its high"]];
  let period = "SI", mode = "nav";

  function segChips(host, items, cur, on) {
    el(host).innerHTML = items.map(([k, t]) =>
      `<button class="chip${k === cur ? " sel" : ""}" data-k="${k}" aria-pressed="${k === cur}">${t}</button>`).join("");
    el(host).querySelectorAll(".chip").forEach((b) => { b.onclick = () => on(b.dataset.k); });
  }
  function navControls() {
    // Periods longer than the record are not offered — a "1Y" button on a 2.4-month fund is a lie.
    segChips("nav-views", PERIODS.filter(([, m]) => m === null || m <= T.months)
      .map(([k]) => [k, k === "SI" ? "Since launch" : k]), period, (k) => { period = k; navControls(); navChart(); });
    segChips("nav-modes", MODES, mode, (k) => { mode = k; navControls(); navChart(); });
  }

  function navChart() {
    const f = fund, refName = D.ref_of[f];
    const i0 = periodStart((PERIODS.find(([k]) => k === period) || [])[1]);
    const dates = D.dates.slice(i0), y = ser(f).slice(i0);
    const r = ser(refName) ? ser(refName).slice(i0) : null;
    const last = dates[dates.length - 1], perLab = period === "SI" ? "since launch" : "last " + period;
    // The name goes INSIDE the tooltip; as a separate "extra" it is drawn outside the box in the
    // series colour, unreadable for the pale identity colours.
    const hoverName = (n) => `  <b>${n}</b><extra></extra>`;
    let tr = [], lay, ann = [];

    if (mode === "dd") {
      // Fall from each series' own running high over the window — what the level chart cannot show.
      const uw = (v) => { let m = -Infinity; return v.map((x) => { m = Math.max(m, x); return x / m - 1; }); };
      const fy = uw(y);
      tr.push({ x: dates, y: fy, name: f, type: "scatter", mode: "lines", fill: "tozeroy",
        fillcolor: "rgba(220,38,38,0.08)", line: { color: COLOR[f], width: 2 },
        hovertemplate: "%{y:.2%}" + hoverName(f) });
      if (r) tr.push({ x: dates, y: uw(r), name: refName, type: "scatter", mode: "lines",
        line: { color: P.ref, width: 1.5, dash: "dot" }, hovertemplate: "%{y:.2%}" + hoverName(refName) });
      const lo = Math.min(...fy, ...(r ? uw(r) : [0]));
      lay = { yaxis: { tickformat: ".1%", range: [lo * 1.25, Math.abs(lo) * 0.08], gridcolor: GRID,
        zeroline: true, zerolinecolor: P.zero, zerolinewidth: 1 } };
      el("nav-chart-title").textContent = `${f} — fall from its high`;
      el("nav-sub").textContent = `${perLab} · ${dates.length} trading days · reference dotted`;
      const worst = Math.min(...fy), wi = fy.indexOf(worst);
      ann.push({ x: dates[wi], y: worst, text: `<b>${pct(worst, 1)}</b> ${fmtD(dates[wi])}`, showarrow: true,
        arrowhead: 0, arrowcolor: P.zero, ax: 0, ay: 22, font: { size: 11, color: INK },
        bgcolor: "rgba(255,255,255,.9)" });
      el("nav-read").innerHTML = `The deepest fall from a high for <strong>${f}</strong> over this window was
        <strong>${pct(worst, 1)}</strong>, reached on ${fmtD(dates[wi])}; it stands
        <strong>${pct(fy[fy.length - 1], 1)}</strong> from its high today. ${r ? `Its reference, dotted, fell
        as far as ${pct(Math.min(...uw(r)), 1)}.` : ""} A fall is measured from the highest NAV reached so far
        in the window, net of fee and dealing.`;
    } else {
      const showRef = mode === "ref" && r;
      // The reference is rebased to the portfolio's own NAV at the start of the window, so both sit on
      // one price axis — no second scale.
      const rr = showRef ? r.map((v) => y[0] * v / r[0]) : null;
      tr.push({ x: dates, y: y, name: f, type: "scatter", mode: "lines",
        line: { color: COLOR[f], width: 2.4, shape: "linear" },
        fill: showRef ? "none" : "tonexty", fillcolor: "rgba(37,99,235,0.06)",
        hovertemplate: "%{y:.2f}" + hoverName(f) });
      if (!showRef) {
        // An invisible floor under the line so the area fill stops at the axis rather than at zero.
        const ax0 = niceAxis(y.concat([D.nav0]));
        tr.unshift({ x: dates, y: dates.map(() => ax0.range[0]), type: "scatter", mode: "lines",
          line: { width: 0 }, hoverinfo: "skip", showlegend: false });
      }
      if (showRef) tr.push({ x: dates, y: rr, name: refName + " (rebased)", type: "scatter", mode: "lines",
        line: { color: P.ref, width: 1.7, dash: "dot" }, hovertemplate: "%{y:.2f}" + hoverName(refName) });
      const vals = y.concat(rr || [], [D.nav0]);
      const ax = niceAxis(vals);
      lay = { yaxis: { range: ax.range, dtick: ax.dtick, tickformat: tickFmtFor(ax.dtick) === ".0f" ? ".0f" : ".1f",
        gridcolor: GRID, zeroline: false } };
      // Launch price as a labelled reference line; the high and low marked on the line itself.
      lay.shapes = [{ type: "line", xref: "paper", x0: 0, x1: 1, y0: D.nav0, y1: D.nav0,
        line: { color: "#8a93a1", width: 1, dash: "dash" } }];
      ann.push({ xref: "paper", x: 0, y: D.nav0, xanchor: "left", yanchor: "bottom", showarrow: false,
        text: `launch ${D.nav0.toFixed(2)}`, font: { size: 10, color: MUTED } });
      const hi = Math.max(...y), lo = Math.min(...y);
      tr.push({ x: [dates[y.indexOf(hi)], dates[y.indexOf(lo)]], y: [hi, lo], type: "scatter", mode: "markers+text",
        text: ["high " + hi.toFixed(2), "low " + lo.toFixed(2)], textposition: ["top center", "bottom center"],
        textfont: { size: 10, color: MUTED },
        marker: { size: 8, color: "#fff", line: { color: COLOR[f], width: 2 } },
        hoverinfo: "skip", showlegend: false });
      // On a phone the end labels carry the value only; the title already names the series.
      const sh = narrow("nav-chart");
      const ends = prep([{ y: y[y.length - 1], t: `<b>${sh ? "" : f + " "}${y[y.length - 1].toFixed(2)}</b>`, c: COLOR[f] }]
        .concat(showRef ? [{ y: rr[rr.length - 1], t: `${sh ? "" : refName + " "}${rr[rr.length - 1].toFixed(2)}`, c: "#6b7783" }] : []));
      declutter(ends, ax.range[1] - ax.range[0], 0.07).forEach((e) => ann.push(endLabel(last, e.ly, e.c, e.t)));
      el("nav-chart-title").textContent = showRef ? `${f} against ${refName}` : `${f} — NAV per unit`;
      el("nav-sub").textContent = `${perLab} · ${dates.length} trading days · net of fee and dealing`
        + (showRef ? " · reference rebased to the portfolio at the start of the window" : "");
      const st = D.stats[f], rs = D.ref_stats[f], chg = y[y.length - 1] / y[0] - 1;
      el("nav-read").innerHTML = showRef
        ? `Over this window <strong>${f}</strong> moved <strong>${pp(chg)}</strong> and ${refName}
           ${pp(r[r.length - 1] / r[0] - 1)}. Since launch the gap is <strong>${pp(rs.excess)}</strong>
           (${pp(st.ret)} against ${pp(rs.ret)}). Both are drawn from the same starting value, so the space
           between the lines is the difference in return.`
        : `<strong>${f}</strong> is priced at <strong>${st.nav.toFixed(2)}</strong>, from ${y[0].toFixed(2)} at the
           start of this window — <strong>${pp(chg)}</strong> ${period === "SI" ? "since launch" : "over the " + period}.
           The dashed line is the ${D.nav0.toFixed(2)} launch price; the open circles mark the high and low of the
           window. Weekends and market holidays are left out of the time axis.`;
    }
    lay.annotations = ann;
    lay.showlegend = false;
    lay.hovermode = "x unified";
    const nw = narrow("nav-chart");
    lay.margin = { l: 44, r: mode === "dd" ? 16 : (nw ? 58 : 150), t: 12, b: 34 };
    lay.xaxis = DATE_AXIS(dates, "nav-chart");
    Plotly.react("nav-chart", tr, L(lay), CFG);
  }
  const endLabel = (x, y, color, text) => ({
    x: x, y: y, xref: "x", yref: "y", text: text, showarrow: false,
    xanchor: "left", xshift: 8, font: { size: 11, color: color === "#6b7783" ? MUTED : INK },
    bgcolor: "rgba(255,255,255,0.9)", bordercolor: color, borderwidth: 0, borderpad: 2
  });
  function hexA(hex, a) {
    const h = hex.replace("#", ""), n = parseInt(h.length === 3 ? h.split("").map((c) => c + c).join("") : h, 16);
    return `rgba(${(n >> 16) & 255},${(n >> 8) & 255},${n & 255},${a})`;
  }

  // ---------- where it sits in the range ----------
  // The analysis a single product page cannot give on its own: each characteristic as a track from the
  // lowest to the highest of the five, this portfolio marked, the other four as ticks. Structural
  // characteristics only — no since-launch return, because ranking five books on 2.4 months is noise.
  function posMeters() {
    const C = D.chars;
    if (!C) { el("pos-meters").innerHTML = `<p class="read">Characteristics not available.</p>`; return; }
    const M = [
      ["Income yield", (c) => c.income_yield, (v) => pct(v, 2), "trailing 12m, across what it holds"],
      ["Equity sensitivity", (c) => c.equity_beta, n2, "beta to global equity over cash"],
      ["Rate sensitivity", (c) => c.rate_beta, n2, "beta to rates and the curve"],
      ["Trend", (c) => c.trend, n2, "beta to managed futures"],
      ["Volatility", (c) => c.vol, (v) => pct(v, 1), "annualised from the live record — short"],
      ["Drawdown cap", (c) => c.dd_cap, (v) => v === null ? "—" : pct(v, 1), "construction constraint"],
    ];
    el("pos-meters").innerHTML = `<div class="lv-meters">` + M.map(([l, get, fmt, h]) => {
      const vals = FUNDS.map((f) => get(C[f])).filter((v) => v !== null && v !== undefined);
      if (!vals.length) return "";
      const lo = Math.min(...vals), hi = Math.max(...vals), span = (hi - lo) || 1;
      const at = (v) => 4 + 92 * (v - lo) / span;
      const me = get(C[fund]);
      const ticks = FUNDS.filter((f) => f !== fund && get(C[f]) !== null).map((f) =>
        `<i class="lv-m-o" style="left:${at(get(C[f])).toFixed(1)}%;--pc:${COLOR[f]}" title="${f}: ${fmt(get(C[f]), C[f])}"></i>`).join("");
      return `<div class="lv-meter">
        <div class="lv-m-top"><span>${l}<em>${h}</em></span><b>${fmt(me, C[fund])}</b></div>
        <div class="lv-m-track">${ticks}
          <i class="lv-m-me" style="left:${at(me).toFixed(1)}%;--pc:${COLOR[fund]}" title="${fund}: ${fmt(me, C[fund])}"></i></div>
        <div class="lv-m-ends"><span>${fmt(lo)}</span><span>${fmt(hi)}</span></div></div>`;
    }).join("") + `</div>`;
    const eq = FUNDS.slice().sort((a, b) => C[a].equity_beta - C[b].equity_beta), pos = eq.indexOf(fund);
    el("pos-read").innerHTML = `Each track runs from the lowest to the highest of the five portfolios; the
      filled marker is <strong>${fund}</strong>, the open ticks are the other four (hover for names). By equity
      sensitivity ${fund} is ${pos === 0 ? "the most defensive of the five" : pos === eq.length - 1
        ? "the most growth-exposed of the five" : `number ${pos + 1} of ${eq.length}, from most defensive to most growth-exposed`}.
      These describe how the book is built, which is what separates the five — not who is ahead.`;
  }

  // ---------- returns: this portfolio, its reference, the market ----------
  function retTable() {
    const f = fund, ref = D.ref_of[f];
    const ALL = [["1M", "1 month"], ["3M", "3 months"], ["6M", "6 months"], ["12M", "12 months"], ["SI", "Since launch"]];
    // A column of em-dashes is not information. Show a period once it has data.
    const COLS = ALL.filter(([k]) => D.periods[f] && D.periods[f][k] !== null && D.periods[f][k] !== undefined);
    const cell = (v) => v === null || v === undefined ? `<td class="num z">—</td>` : `<td class="num ${cls(v)}">${pp(v)}</td>`;
    const row = (n, c, label) => `<tr class="${c || ""}"><td>${label || n}</td>${COLS.map(([k]) => cell((D.periods[n] || {})[k])).join("")}</tr>`;
    const diff = COLS.map(([k]) => {
      const a = D.periods[f][k], b = (D.periods[ref] || {})[k];
      return a === null || b === null || b === undefined ? `<td class="num z">—</td>`
        : `<td class="num ${cls(a - b)}"><b>${pp(a - b)}</b></td>`;
    }).join("");
    el("ret-sub").textContent = "cumulative, not annualised · net of fee and dealing";
    el("ret-table").innerHTML = `<table class="dtbl lv-tbl"><thead><tr><th></th>${COLS.map(([k, t]) =>
      `<th class="num" title="${t}">${k === "SI" ? "Since launch" : t}</th>`).join("")}</tr></thead><tbody>
      ${row(f, "lv-me", `<span class="lv-dot" style="--pc:${COLOR[f]}"></span><strong>${f}</strong>`)}
      ${row(ref, "", `<span class="lv-dot lv-dot-ref"></span>${ref} <span class="z">reference</span>`)}
      <tr class="lv-diff"><td>Difference <span class="z">portfolio − reference</span></td>${diff}</tr>
      <tr class="lv-grp"><td colspan="${COLS.length + 1}">Market benchmarks</td></tr>
      ${BENCH.filter((b) => b !== ref).map((b) => row(b, "", `<span class="z">${b}</span>`)).join("")}
      </tbody></table>`;
    el("ret-read").innerHTML = `${T.note} Periods longer than the record are not shown — the portfolios were
      launched ${T.months.toFixed(1)} months ago. The difference is arithmetic: the portfolio's return minus
      its reference's, the one definition of excess used across this page.`;
  }

  // ---------- risk and the benchmarks ----------
  function riskPanel() {
    const f = fund, st = D.stats[f];
    el("risk-sub").textContent = `${st.n} daily observations · indicative only`;
    const s = (v, l, c) => `<div class="lv-rs"><b class="${c || ""}">${v}</b><span>${l}</span></div>`;
    el("risk-stats").innerHTML = `<div class="lv-rstats">
      ${s(pct(st.vol, 1), "volatility, annualised")}
      ${s(pct(st.maxdd, 1), "worst drop since launch", "neg")}
      ${s(pp(st.best), "best day", "pos")}
      ${s(pp(st.worst), "worst day", "neg")}
      ${s(st.up + "/" + st.n, "days up")}</div>`;
    let h = `<table class="dtbl lv-tbl"><thead><tr><th>Against</th><th class="num">Excess</th>
      <th class="num">Tracking error</th><th class="num">Beta</th></tr></thead><tbody>`;
    BENCH.forEach((b) => {
      const r = D.rel[f][b];
      h += `<tr><td>${b}</td><td class="num ${cls(r.excess)}">${pp(r.excess)}</td>
        <td class="num">${pct(r.te, 1)}</td><td class="num">${r.beta.toFixed(2)}</td></tr>`;
    });
    el("rel-table").innerHTML = h + "</tbody></table>";
    el("risk-read").innerHTML = `Volatility and tracking error are annualised from ${st.n} daily observations;
      the convention is ${T.min_months_for_risk_stats} months before a risk statistic is quoted as an estimate,
      so read these as a description of this window and nothing more. Two months is far too short to judge a
      strategy — the case for ${f} is its construction, set out in Construction and Methodology.`;
  }

  // ---------- month by month: portfolio against its reference ----------
  function monthPanel() {
    const f = fund, ref = D.ref_of[f], mf = D.monthly[f], mr = D.monthly[ref] || [];
    const lbl = (m) => new Date(m.month + "-01T00:00:00").toLocaleDateString("en-GB", { month: "short", year: "numeric" })
      + (m.partial ? "*" : "");
    const xs = mf.map(lbl);
    el("mm-sub").textContent = `${f} against ${ref} · calendar months · * partial`;
    const mk = (arr, name, color) => ({
      type: "bar", name: name, x: xs, y: arr.map((m) => m.ret), marker: { color: color },
      text: arr.map((m) => pp(m.ret, 1)), textposition: "outside", cliponaxis: false,
      textfont: { size: 10, color: INK }, hovertemplate: "%{y:+.2%}  <b>" + name + "</b><extra></extra>" });
    const allv = mf.map((m) => m.ret).concat(mr.map((m) => m.ret), [0]);
    const pad = (Math.max(...allv) - Math.min(...allv)) * 0.25 || 0.01;
    Plotly.react("mm-chart", [mk(mf, f, MAG), mk(mr, ref, P.refLight)], L({
      barmode: "group", bargap: 0.35, bargroupgap: 0.08, showlegend: true,
      legend: { orientation: "h", x: 0, y: 1.14, font: { size: 11 } },
      margin: { l: 46, r: 10, t: 28, b: 28 },
      xaxis: { type: "category", showgrid: false },
      yaxis: { tickformat: ".0%", range: [Math.min(...allv) - pad, Math.max(...allv) + pad],
        zeroline: true, zerolinecolor: P.zero }
    }), CFG);
    const m2 = Object.fromEntries(mr.map((m) => [m.month, m.ret]));
    el("mm-table").innerHTML = `<table class="dtbl lv-tbl"><thead><tr><th>Month</th><th class="num">${f}</th>
      <th class="num">${ref}</th><th class="num">Difference</th></tr></thead><tbody>` +
      mf.map((m) => {
        const r = m2[m.month];
        return `<tr><td>${lbl(m)}<span class="z"> · ${m.days} days</span></td><td class="num ${cls(m.ret)}">${pp(m.ret)}</td>
          <td class="num ${r === undefined ? "z" : cls(r)}">${r === undefined ? "—" : pp(r)}</td>
          <td class="num ${r === undefined ? "z" : cls(m.ret - r)}">${r === undefined ? "—" : "<b>" + pp(m.ret - r) + "</b>"}</td></tr>`;
      }).join("") + `</tbody></table>
      <p class="read">* partial month — launched ${fmtD(D.inception)}, priced to ${fmtD(D.asof)}. Cumulative
      within the month, net of fee and dealing. The reference is rebalanced daily from MSCI ACWI and the
      Bloomberg Aggregate${ref === "S&P 500" ? " — for Alpha it is the S&P 500 itself" : ""}.</p>`;
  }

  // ---------- holdings ----------
  // Weight and what each line has earned since launch, side by side: the two facts a holder asks of a
  // holding. A vehicle sold since launch still shows its contribution, at zero weight.
  function holdTable() {
    const f = fund, h = D.holdings[f], B = D.bridge[f];
    const tick = [...new Set(Object.keys(h).concat(Object.keys(B.vehicles || {})))]
      .sort((a, b) => (h[b] || 0) - (h[a] || 0));
    const wmax = Math.max(...Object.values(h));
    const cmax = Math.max(...Object.values(B.vehicles || { x: 0 }).map(Math.abs), 1e-9);
    const tot = Object.values(h).reduce((a, c) => a + c, 0);
    const csum = Object.values(B.vehicles || {}).reduce((a, c) => a + c, 0);
    el("hold-sub").textContent = `${f} · ${Object.keys(h).length} holdings · today's weights`;
    el("hold-table").innerHTML = `<table class="dtbl lv-tbl lv-hold"><thead><tr><th>Vehicle</th><th>Sleeve</th>
      <th class="num">Weight</th><th class="lv-barh"></th><th class="num">Since launch</th><th class="lv-barh lv-cbarh">points of NAV</th></tr></thead><tbody>` +
      tick.map((t) => {
        const w = h[t] || 0, c = (B.vehicles || {})[t], sl = D.ticker_sleeve[t];
        const cb = c === undefined ? "" : `<span class="lv-cbar"><span class="${c >= 0 ? "p" : "n"}" style="width:${
          (50 * Math.abs(c) / cmax).toFixed(1)}%"></span></span>`;
        return `<tr><td class="strong">${t}</td><td class="z">${sl ? lab(sl) : ""}</td>
          <td class="num">${w ? pct(w, 1) : '<span class="z">sold</span>'}</td>
          <td class="lv-barc"><span class="lv-wbar" style="--pc:${MAG}"><span style="width:${(100 * w / wmax).toFixed(1)}%"></span></span></td>
          <td class="num ${c === undefined ? "z" : cls(c)}">${c === undefined ? "—" : sgn(c, 3)}</td>
          <td class="lv-barc">${cb}</td></tr>`;
      }).join("") +
      `<tr class="lv-total"><td class="strong">Total</td><td></td><td class="num">${pct(tot, 1)}</td><td></td>
        <td class="num ${cls(csum)}">${sgn(csum, 3)}</td><td class="z lv-note">before ${sgn(B.dealing + B.fee, 3)} of costs</td></tr>
      </tbody></table>`;
    el("hold-read").innerHTML =
      `Weights drift with markets between rebalances, so these are today's actual weights rather than the
       targets. A sleeve above the ${(F0.vehicle_cap * 100).toFixed(0)}% vehicle cap is split across
       issuers, so no equity or bond line breaches it. The cap cannot bind a sleeve with a single
       vehicle: Certain's T-bill position is one holding and runs above it by design. Contributions are in
       points of NAV; with costs they add to the NAV exactly — see section 03.`;
  }

  // ---------- exposure ----------
  // Exposure of what is HELD today, on the platform's two established taxonomies. The methodology
  // classes drive the optimiser; the platform's six drive the shared components; the crosswalk
  // between them is an owner-confirmed decision. Geography is equity-only on purpose — assigning one
  // to gold or a trend sleeve would invent a mapping that appears in no approved document.
  let expoView = "methodology";
  function barList(obj, order, color) {
    const keys = (order || Object.keys(obj)).filter((k) => (obj[k] || 0) > 0.05);
    if (!order) keys.sort((a, b) => obj[b] - obj[a]);
    const mx = Math.max(...keys.map((k) => obj[k]), 1);
    return `<div class="lv-bars">` + keys.map((k) => `<div class="lv-bar"><span class="lv-bar-l">${k}</span>
      <span class="lv-bar-t" style="--pc:${color}"><span style="width:${(100 * obj[k] / mx).toFixed(1)}%"></span></span>
      <b>${obj[k].toFixed(1)}%</b></div>`).join("") + `</div>`;
  }
  function exposurePanel() {
    const f = fund, E = D.exposure && D.exposure[f];
    if (!E) { el("expo-sub").textContent = "exposure not available"; return; }
    el("expo-sub").textContent = `${f} · share of what is held today`;
    segChips("expo-views", [["methodology", "Asset class"], ["platform", "Platform class"], ["sleeves", "Sleeve"]],
      expoView, (k) => { expoView = k; exposurePanel(); });
    const order = expoView === "methodology" ? D.methodology_classes : expoView === "platform" ? D.platform_classes : null;
    el("expo-class").innerHTML = barList(E[expoView], order, MAG);
    el("expo-geo").innerHTML = Object.keys(E.equity_geography).length
      ? barList(E.equity_geography, ["United States", "Developed ex-US", "Emerging markets"], MAG)
        + `<div class="lv-note z">share of the equity held, ${E.equity_weight.toFixed(1)}% of the book</div>`
      : `<p class="read">${f} holds no equity.</p>`;
    const us = E.equity_geography["United States"];
    el("expo-read").innerHTML =
      `${f} holds <strong>${E.equity_weight.toFixed(1)}%</strong> in equity${
        us === undefined ? "" : `, <strong>${us.toFixed(0)}%</strong> of it in the United States`}.
       Two class views are kept on purpose: the portfolios' own methodology classes drive the optimiser, the
       platform's six drive its shared components, and the crosswalk between them is an owner decision —
       gold reads as a real asset in one and a commodity in the other. Geography is equity-only: gold, broad
       commodities and the trend sleeve have no defensible country of risk, so none is asserted.`;
  }

  function dealingPanel() {
    const f = fund, tr = D.trades[f] || [];
    el("trade-table").innerHTML = tr.length
      ? `<table class="dtbl lv-tbl"><thead><tr><th>Date</th><th>Event</th><th class="num">Turnover</th></tr></thead><tbody>` +
        tr.map((x) => `<tr><td>${fmtD(x.date)}</td><td class="z">${x.date === D.inception ? "funded at launch" : "rebalance"}</td>
          <td class="num">${x.turnover.toFixed(1)}%</td></tr>`).join("") + `</tbody></table>`
      : `<p class="read">Funded at inception and not dealt since — no holding has drifted a full point from target.</p>`;
    const b = D.backtest[f];
    el("bt-table").innerHTML = `<table class="dtbl lv-tbl"><tbody>
      <tr><td>Return, 1997–2026</td><td class="num">${b.cagr.toFixed(2)}% a year</td></tr>
      <tr><td>Volatility</td><td class="num">${b.vol.toFixed(1)}% a year</td></tr>
      <tr><td>Sharpe</td><td class="num">${b.sharpe.toFixed(2)}</td></tr>
      <tr><td>Worst loss</td><td class="num neg">${b.maxdd.toFixed(1)}%</td></tr></tbody></table>
      <p class="read">A <strong>backtest of today's weights</strong> over ${b.n} months — the long-run evidence
      behind ${f}, on a different basis from the live NAV and not continued by it.</p>`;
  }

  // ---------- what moved the NAV: by holding ----------
  // fund_nav.py scales each day's contribution by the NAV level it was earned on and refuses to write
  // a bridge that does not reconcile, so these pieces sum to the NAV exactly. Drawn as a bridge from
  // the launch price to today's NAV, sleeve by sleeve, then costs.
  function rowsHeight(id, n) {
    const h = Math.max(340, n * 30 + 70), c = el(id);
    if (c && Math.abs(c.offsetHeight - h) > 6) c.style.height = h + "px";
  }
  function bridgePanel() {
    const f = fund, B = D.bridge[f];
    rowsHeight("bridge-chart", Object.keys(B.sleeves).length + 3);
    const sl = Object.entries(B.sleeves).map(([k, v]) => [lab(k), v]).sort((a, b) => b[1] - a[1]);
    const steps = sl.concat([["Dealing", B.dealing], ["Fee", B.fee]]);
    el("bridge-sub").textContent = `${f} · points of NAV · ${D.nav0.toFixed(2)} at launch to ${(D.nav0 + B.total).toFixed(2)} today`;
    // Each step is drawn on a base of the launch NAV, so the bar positions ARE NAV levels: the bridge
    // walks from 100.00 to today's price and the final bar spans launch to today.
    const ys = steps.map((s) => s[0]).concat(["NAV today"]);
    const xs = steps.map((s) => s[1]).concat([0]);
    const cum = [D.nav0]; steps.forEach((s) => cum.push(cum[cum.length - 1] + s[1]));
    const lo = Math.min(...cum), hi = Math.max(...cum), pad = (hi - lo) * 0.16 || 0.5;
    Plotly.react("bridge-chart", [{
      type: "waterfall", orientation: "h", y: ys, x: xs, base: D.nav0,
      measure: steps.map(() => "relative").concat(["total"]),
      connector: { line: { color: "#c9d1da", width: 1, dash: "dot" } },
      increasing: { marker: { color: P.gain } }, decreasing: { marker: { color: P.loss } },
      totals: { marker: { color: P.accent } },
      text: steps.map((s) => sgn(s[1], 2)).concat([`${(D.nav0 + B.total).toFixed(2)} (${sgn(B.total, 2)})`]),
      // On a phone the values would collide with the category labels; the table beside it has them.
      textposition: narrow("bridge-chart") ? "none" : "outside", cliponaxis: false, textfont: { size: 10, color: INK },
      hovertemplate: "%{y}: %{text}<extra></extra>"
    }], L({
      showlegend: false, bargap: 0.3, margin: { l: narrow("bridge-chart") ? 120 : 160, r: 70, t: 6, b: 34 },
      xaxis: { type: "linear", range: [lo - pad, hi + pad], title: { text: "NAV per unit — launch at " + D.nav0.toFixed(2), font: { size: 10 } },
        tickformat: ".1f", showgrid: true, nticks: narrow("bridge-chart") ? 3 : 8, tickangle: 0 },
      yaxis: { type: "category", autorange: "reversed", automargin: true, tickfont: { size: 11 } },
      shapes: [{ type: "line", yref: "paper", y0: 0, y1: 1, x0: D.nav0, x1: D.nav0,
        line: { color: "#8a93a1", width: 1, dash: "dash" } }]
    }), CFG);

    const r = (n, v, c) => `<tr class="${c || ""}"><td>${n}</td>
      <td class="num ${cls(v)}">${sgn(v, 3)}</td></tr>`;
    const veh = Object.entries(B.vehicles).sort((a, b) => b[1] - a[1]);
    el("bridge-table").innerHTML = `<table class="dtbl lv-tbl"><thead><tr><th>Vehicle</th><th class="num">Points</th></tr></thead><tbody>
      ${veh.map(([k, v]) => r(`<strong>${k}</strong> <span class="z">${lab(D.ticker_sleeve[k] || "")}</span>`, v)).join("")}
      ${r("Dealing", B.dealing)}${r("Fee", B.fee)}
      ${r("<strong>Net asset value</strong> <span class=\"z\">change since launch</span>", B.total, "lv-total")}</tbody></table>`;

    const top = sl.filter((i) => i[1] > 0)[0], worst = steps.slice().sort((a, b) => a[1] - b[1])[0];
    el("bridge-read").innerHTML =
      `${f} is ${pp(B.total / 100)} since launch. ${top ? `<strong>${top[0]}</strong> is the largest positive
       contributor at ${sgn(top[1])} points and ` : ""}<strong>${worst[0]}</strong> the largest drag at
       ${sgn(worst[1])}. Costs took ${Math.abs(B.dealing + B.fee).toFixed(3)} points —
       ${Math.abs(B.fee).toFixed(3)} of it the management fee, the rest the dealing to buy the book at launch
       and rebalance it. Contributions are measured on the NAV level each day's return was earned on, so the
       bridge lands on the NAV exactly.`;
  }

  // ---------- what the book was EXPOSED to ----------
  // The holdings bridge says which line moved the NAV. This says what the book was positioned in and
  // what that position paid. Exposures are not estimated from the fund's own 51 days — that would be
  // noise — they are the real daily weights times each vehicle's betas, fitted on years of history.
  // Whatever the factors do not explain is shown as a residual rather than spread over them.
  function facPanel() {
    const FA = D.factor;
    if (!FA) { el("fac-sub").textContent = "factor attribution not available"; return; }
    const f = fund, A = FA.funds[f], w = FA.window;
    rowsHeight("fac-chart", A.factors.length + 3);
    el("fac-sub").textContent = `${f} · ${FA.factor_defs.length} factors · `
      + `betas fitted on ${w.beta_obs.toLocaleString("en-GB")} days from ${fmtD(w.beta_start)} · points of NAV`;
    const rows = A.factors.map((x) => [x.name, x.contrib, true])
      .concat([["Cash", A.cash, false], ["Costs", A.costs, false], ["Unexplained", A.residual, false]])
      .sort((a, b) => b[1] - a[1]);
    const mx = Math.max(...rows.map((r) => Math.abs(r[1])));
    Plotly.react("fac-chart", [{
      type: "bar", orientation: "h",
      y: rows.map((r) => r[0]).reverse(), x: rows.map((r) => r[1]).reverse(),
      marker: { color: rows.map((r) => !r[2] ? (r[1] >= 0 ? P.gainQuiet : P.lossQuiet)
        : (r[1] >= 0 ? P.gain : P.loss)).reverse() },
      text: rows.map((r) => sgn(r[1], 2)).reverse(), textposition: narrow("fac-chart") ? "none" : "outside", cliponaxis: false,
      textfont: { size: 10, color: INK },
      hovertemplate: "%{y}: %{x:+.3f} pts<extra></extra>"
    }], L({
      showlegend: false, bargap: 0.3, margin: { l: 96, r: 40, t: 6, b: 30 },
      xaxis: { type: "linear", range: [-mx * 1.3, mx * 1.3], title: { text: "points of NAV", font: { size: 10 } },
        zeroline: true, zerolinecolor: P.zero },
      yaxis: { type: "category", automargin: true, tickfont: { size: 11 } }
    }), CFG);

    const num = (v, d = 3) => sgn(v, d);
    const fr = A.factors.slice().sort((a, b) => Math.abs(b.contrib) - Math.abs(a.contrib)).map((x) =>
      `<tr><td>${x.name}<div class="z lv-hint">${x.blurb}</div></td><td class="num">${n2(x.exposure)}</td>
      <td class="num ${cls(x.fret)}">${pp(x.fret, 1)}</td><td class="num ${cls(x.contrib)}">${num(x.contrib)}</td></tr>`).join("");
    el("fac-table").innerHTML = `<table class="dtbl lv-tbl"><thead><tr><th>Factor</th>
      <th class="num">Exposure</th><th class="num">Factor return</th><th class="num">Points</th></tr></thead>
      <tbody>${fr}
      <tr class="lv-grp"><td colspan="4">Outside the factors</td></tr>
      <tr><td>Cash<div class="z lv-hint">earned on the whole book</div></td><td class="num z">1.00</td>
        <td class="num z">—</td><td class="num ${cls(A.cash)}">${num(A.cash)}</td></tr>
      <tr><td>Costs<div class="z lv-hint">fee and dealing</div></td><td class="num z">—</td>
        <td class="num z">—</td><td class="num ${cls(A.costs)}">${num(A.costs)}</td></tr>
      <tr><td>Unexplained<div class="z lv-hint">what the factors do not account for</div></td>
        <td class="num z">—</td><td class="num z">—</td><td class="num ${cls(A.residual)}">${num(A.residual)}</td></tr>
      <tr class="lv-total"><td><strong>Net asset value</strong></td><td class="num z">—</td>
        <td class="num z">—</td><td class="num ${cls(A.total)}">${num(A.total)}</td></tr>
      </tbody></table>`;

    const byAbs = A.factors.slice().sort((a, b) => Math.abs(b.contrib) - Math.abs(a.contrib));
    const sz = A.factors.find((x) => x.name === "Size"), va = A.factors.find((x) => x.name === "Value");
    el("fac-read").innerHTML =
      `<strong>${byAbs[0].name}</strong> is the exposure that mattered most for ${f}
       (${num(byAbs[0].contrib, 2)} points, from an exposure of ${n2(byAbs[0].exposure)} to a
       factor that returned ${pp(byAbs[0].fret, 1)}), then <strong>${byAbs[1].name}</strong> at
       ${num(byAbs[1].contrib, 2)}.${sz && va ? ` On the size and style dimensions the methodology formalises as
       the 3x3 style box (on Attribution), this book takes essentially no bet: <strong>size ${n2(sz.exposure)}</strong>
       and <strong>value ${n2(va.exposure)}</strong>. Small beat big by ${pp(sz.fret, 1)} and value by
       ${pp(va.fret, 1)} over the window, so not taking those bets was worth ${num(sz.contrib + va.contrib, 2)}
       points — a non-decision with a visible price.` : ""}
       <strong>${num(A.residual, 2)}</strong> is unexplained: vehicle behaviour the ${FA.factor_defs.length} factors
       do not span, shown rather than folded into them.`;
  }

  // ================================================================================================
  // RANGE — all five side by side
  // ================================================================================================
  let rangeBench = false, rangePeriod = "SI";
  function rangeControls() {
    const items = PERIODS.filter(([, m]) => m === null || m <= T.months)
      .map(([k]) => [k, k === "SI" ? "Since launch" : k]).concat([["__b", "Market benchmarks"]]);
    el("range-views").innerHTML = items.map(([k, t]) => {
      const on = k === "__b" ? rangeBench : k === rangePeriod;
      return `<button class="chip${on ? " sel" : ""}${k === "__b" ? " lv-toggle" : ""}" data-k="${k}" aria-pressed="${on}">${t}</button>`;
    }).join("");
    el("range-views").querySelectorAll(".chip").forEach((b) => {
      b.onclick = () => { if (b.dataset.k === "__b") rangeBench = !rangeBench; else rangePeriod = b.dataset.k;
        rangeControls(); rangeChart(); };
    });
  }

  // All five on one axis. The registry's identity colours are too close to separate five lines by hue
  // alone (SAA and Endowment, SAA and Certain), so the selected portfolio is drawn in its colour and
  // weight, the other four quieter, and every line is named at its end. Click a line to select it.
  function rangeChart() {
    const i0 = periodStart((PERIODS.find(([k]) => k === rangePeriod) || [])[1]);
    const dates = D.dates.slice(i0), last = dates[dates.length - 1];
    const tr = [];
    const others = FUNDS.filter((f) => f !== fund);
    if (rangeBench) BENCH.filter((b) => ser(b)).forEach((b) => tr.push({
      x: dates, y: ser(b).slice(i0),
      name: b, type: "scatter", mode: "lines", line: { color: "#aab3bd", width: 1.3, dash: "dot" },
      hovertemplate: "%{y:.2f}  " + b + "<extra></extra>" }));
    others.concat([fund]).forEach((f) => tr.push({
      x: dates, y: ser(f).slice(i0), name: f, type: "scatter", mode: "lines",
      line: { color: f === fund ? COLOR[f] : hexA(COLOR[f], 0.55), width: f === fund ? 3 : 1.6 },
      hovertemplate: "%{y:.2f}  <b>" + f + "</b><extra></extra>" }));
    const vals = tr.reduce((a, t) => a.concat(t.y), [D.nav0]);
    const ax = niceAxis(vals, 0.12);
    const ends = prep(tr.map((t) => ({ y: t.y[t.y.length - 1], n: t.name, bench: BENCH.includes(t.name) })));
    declutter(ends, ax.range[1] - ax.range[0], 0.055);
    const ann = ends.map((e) => ({
      x: last, y: e.ly, xref: "x", yref: "y", xanchor: "left", xshift: 8, showarrow: false,
      text: e.bench ? `<span style="color:${P.ref}">${e.n} ${e.y.toFixed(2)}</span>`
        : `<span style="color:${COLOR[e.n]}">■</span> ${e.n === fund ? "<b>" + e.n + " " + e.y.toFixed(2) + "</b>" : e.n + " " + e.y.toFixed(2)}`,
      font: { size: 11, color: INK } }));
    ann.push({ xref: "paper", x: 0, y: D.nav0, xanchor: "left", yanchor: "bottom", showarrow: false,
      text: `launch ${D.nav0.toFixed(2)}`, font: { size: 10, color: MUTED } });
    Plotly.react("range-chart", tr, L({
      showlegend: false, hovermode: "x unified", margin: { l: 44, r: narrow("range-chart") ? 120 : 190, t: 12, b: 34 },
      xaxis: DATE_AXIS(dates, "range-chart"),
      yaxis: { range: ax.range, dtick: ax.dtick, tickformat: tickFmtFor(ax.dtick) === ".0f" ? ".0f" : ".1f" },
      shapes: [{ type: "line", xref: "paper", x0: 0, x1: 1, y0: D.nav0, y1: D.nav0,
        line: { color: "#8a93a1", width: 1, dash: "dash" } }],
      annotations: ann
    }), CFG);
    const node = el("range-chart");
    if (!node.__lvClick) {
      node.__lvClick = true;
      node.on("plotly_click", (ev) => { const n = ev.points && ev.points[0] && ev.points[0].data.name;
        if (FUNDS.includes(n)) select(n); });
    }
    const navs = FUNDS.map((f) => ser(f)[ser(f).length - 1]);
    el("range-sub").textContent = `${rangePeriod === "SI" ? "since launch" : "last " + rangePeriod} · every series starts at `
      + `${D.nav0.toFixed(2)} at launch · ${fund} highlighted — click a line to select a portfolio`;
    el("range-read").innerHTML = `All five started at ${D.nav0.toFixed(2)} on the same day, so the lines are
      directly comparable. They span ${Math.min(...navs).toFixed(2)} to ${Math.max(...navs).toFixed(2)} today — a
      ${(Math.max(...navs) - Math.min(...navs)).toFixed(2)} point spread in ${T.months.toFixed(1)} months, which is
      dispersion between mandates built for different jobs, not a ranking worth acting on at this length.`;
  }

  function insight() {
    el("funds-insight").innerHTML =
      `<strong>Certain</strong> preserves purchasing power — short duration, TIPS-led, with gold and the Swiss
       franc as its store of value. <strong>Endowment</strong> is the endowment model made liquid, real assets a
       quarter of the fund. The <strong>SAA</strong> is the house policy portfolio, nine holdings and deliberately
       lean. The <strong>DAA</strong> runs that book actively, sizing its trend sleeve to the macro state — which
       reads <strong>${D.regime.toLowerCase()}</strong> today. <strong>Alpha</strong> spends an equity-level
       volatility budget of its own. None of them holds mortgage bonds.`;
  }

  // A clickable portfolio header, used by every five-across table so the range is also a way in.
  const fundTh = (f) => `<th class="num lv-fh${f === fund ? " lv-sel" : ""}" data-f="${f}" style="--pc:${COLOR[f]}"
    title="Show ${f}"><span class="lv-dot" style="--pc:${COLOR[f]}"></span>${f}</th>`;
  const selCol = (f) => (f === fund ? " lv-sel" : "");
  // Headers and rows that select a portfolio work from the keyboard too, not only the mouse.
  function bindHeads(host) {
    el(host).querySelectorAll("[data-f]").forEach((n) => {
      const go = () => { select(n.dataset.f); el("lv-hero").scrollIntoView({ behavior: "smooth", block: "start" }); };
      n.tabIndex = 0; n.setAttribute("role", "button");
      n.setAttribute("aria-label", `Show ${n.dataset.f}`);
      n.onclick = go;
      n.onkeydown = (e) => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); go(); } };
    });
  }

  // What actually separates five multi-asset books. Not the sector split of one equity sleeve — these
  // hold equity, two bond durations, real assets, trend and cash, so the questions are how much
  // income they throw off and what they are sensitive to. Shown five-across because the difference
  // between them IS the product.
  function charsTable() {
    const C = D.chars;
    if (!C) { el("chars-sub").textContent = "characteristics not available"; return; }
    el("chars-sub").textContent =
      `income yield weighted from today's holdings · sensitivities measured, not declared`;
    const row = (label, get, fmt, hint) => `<tr><td>${label}${hint ? `<div class="z lv-hint">${hint}</div>` : ""}</td>`
      + FUNDS.map((f) => `<td class="num${selCol(f)}">${fmt(get(C[f]), C[f])}</td>`).join("") + `</tr>`;
    el("chars-table").innerHTML = `<table class="dtbl lv-tbl lv-five"><thead><tr><th>Characteristic</th>
      ${FUNDS.map(fundTh).join("")}</tr></thead><tbody>
      ${row("Income yield", (c) => c.income_yield, (v) => pct(v, 2), "trailing 12m, weighted across what it holds")}
      ${row("Equity sensitivity", (c) => c.equity_beta, n2, "beta to global equity over cash")}
      ${row("Rate sensitivity", (c) => c.rate_beta, n2, "beta to rates and the curve, combined")}
      ${row("Gold", (c) => c.gold, n2, "beta to gold over cash")}
      ${row("Trend", (c) => c.trend, n2, "beta to managed futures over cash")}
      ${row("Volatility", (c) => c.vol, (v) => pct(v, 1), "annualised from the live record — short")}
      ${row("Worst drop", (c) => c.maxdd, (v) => pct(v, 1), "measured, since launch")}
      ${row("Drawdown cap", (c) => c.dd_cap, (v, c) => v === null ? "—" : pct(v, 1)
        + (c.dd_loosened ? '<span class="z">*</span>' : ""), "construction constraint — what the optimiser was held to")}
      ${row("Holdings", (c) => c.n_holdings, (v) => v)}
      </tbody></table>`;
    bindHeads("chars-table");
    const y = FUNDS.map((f) => C[f].income_yield);
    el("chars-read").innerHTML =
      `The ladder is visible in one row: income falls from <strong>${pct(Math.max(...y), 2)}</strong>
       in ${FUNDS[y.indexOf(Math.max(...y))]} to <strong>${pct(Math.min(...y), 2)}</strong> in
       ${FUNDS[y.indexOf(Math.min(...y))]} as equity sensitivity rises from
       ${n2(C[FUNDS[0]].equity_beta)} to ${n2(C[FUNDS[FUNDS.length - 1]].equity_beta)}. That is the
       range doing what it says: the conservative books are paid to wait, the growth books are not.
       <strong>Effective duration is deliberately absent</strong> — no vehicle reports it and a figure
       invented from a maturity guess would not trace to a source, so rate sensitivity is given
       instead, measured against the rate and curve factors. The drawdown cap is a
       <strong>construction constraint</strong> — the limit the optimiser was actually held to, read
       from the build record — not a mandate limit and not a budget.${
        FUNDS.some((f) => C[f].dd_loosened)
          ? ` <strong>*</strong> ${FUNDS.filter((f) => C[f].dd_loosened).join(", ")}: the declared
             conditional-drawdown constraint (${FUNDS.filter((f) => C[f].dd_loosened)
               .map((f) => pct(C[f].cdar_declared, 0)).join(", ")}) was infeasible, so the book was
             solved under the tightest feasible pair — the cap shown is the one it was actually held
             to, not the one declared.` : ""}`;
  }

  function perfTable() {
    // Discrete cumulative periods, the order a factsheet prints them. A period shorter than the
    // record is left out rather than part-filled, and nothing here is annualised — see T.note.
    const ALL_COLS = [["1M", "1 month"], ["3M", "3 months"], ["6M", "6 months"],
                      ["12M", "12 months"], ["SI", "Since inception"]];
    const COLS = ALL_COLS.filter(([k]) =>
      [...FUNDS, ...BENCH].some((n) => D.periods[n] && D.periods[n][k] !== null));
    el("perf-sub").textContent = `cumulative, not annualised · net of fee and dealing · `
      + `${T.trading_days} trading days priced`;
    const row = (n) => {
      const s = D.stats[n], pr = D.periods[n], isF = FUNDS.includes(n);
      const cells = COLS.map(([k]) => pr[k] === null || pr[k] === undefined
        ? `<td class="num z">—</td>` : `<td class="num ${cls(pr[k])}">${pp(pr[k])}</td>`).join("");
      return `<tr class="${isF ? "lv-frow" : ""}${n === fund ? " lv-me" : ""}"${isF ? ` data-f="${n}"` : ""}>
        <td class="${isF ? "strong" : "z"}">${isF ? `<span class="lv-dot" style="--pc:${COLOR[n]}"></span>` : ""}${n}</td>
        <td class="num">${s.nav.toFixed(2)}</td>${cells}
        <td class="num">${pct(s.vol, 1)}</td><td class="num neg">${pct(s.maxdd, 1)}</td></tr>`;
    };
    el("perf-table").innerHTML = `<table class="dtbl lv-tbl"><thead><tr><th>Portfolio or benchmark</th>
      <th class="num">NAV</th>${COLS.map(([k, t]) => `<th class="num" title="${t}">${k}</th>`).join("")}
      <th class="num">Vol<span class="z">†</span></th><th class="num">Worst drop</th></tr></thead>
      <tbody>${FUNDS.map(row).join("")}<tr class="lv-grp"><td colspan="${COLS.length + 4}">Market benchmarks</td></tr>
      ${BENCH.map(row).join("")}</tbody></table>`;
    bindHeads("perf-table");
    el("perf-read").innerHTML = `In the range's own order, not ranked. Nothing is annualised: the record is
      ${T.months.toFixed(1)} months long. <strong>†</strong> volatility is annualised from ${T.trading_days - 1} daily
      observations — a description of this window, not an estimate.`;
  }

  function monthlyTable() {
    const months = D.monthly[FUNDS[0]].map((m) => m.month);
    el("monthly-sub").textContent = `calendar months · first and last are partial · ${months.length} so far`;
    const head = months.map((m) => {
      const p = D.monthly[FUNDS[0]].find((x) => x.month === m);
      const d = new Date(m + "-01T00:00:00");
      return `<th class="num">${d.toLocaleDateString("en-GB", { month: "short" })}${p.partial ? '<span class="z">*</span>' : ""}</th>`;
    }).join("");
    const row = (n) => {
      const isF = FUNDS.includes(n);
      const cells = D.monthly[n].map((m) => `<td class="num ${cls(m.ret)}">${pp(m.ret)}</td>`).join("");
      return `<tr class="${isF ? "lv-frow" : ""}${n === fund ? " lv-me" : ""}"${isF ? ` data-f="${n}"` : ""}>
        <td class="${isF ? "strong" : "z"}">${isF ? `<span class="lv-dot" style="--pc:${COLOR[n]}"></span>` : ""}${n}</td>${cells}</tr>`;
    };
    // The references each portfolio is actually measured against, so the month-by-month comparison
    // is like-for-like rather than everything against the S&P.
    const REFS = [...new Set(FUNDS.map((f) => D.ref_of[f]))].filter((r) => !BENCH.includes(r));
    el("monthly-table").innerHTML = `<table class="dtbl lv-tbl"><thead><tr><th>Portfolio or benchmark</th>
      ${head}</tr></thead><tbody>${FUNDS.map(row).join("")}
      <tr class="lv-grp"><td colspan="${months.length + 1}">Benchmarks and references</td></tr>
      ${BENCH.map(row).join("")}${REFS.map(row).join("")}</tbody></table>
      <p class="read">The last rows are the blended references the portfolios are measured against,
      rebalanced daily from MSCI ACWI and the Bloomberg Aggregate. <strong>*</strong> partial month — the
      portfolios launched on ${fmtD(D.inception)} and the current month is priced to ${fmtD(D.asof)}.</p>`;
    bindHeads("monthly-table");
  }

  function mandateTable() {
    const sleeves = Object.keys(D.labels).filter((s) => FUNDS.some((f) => (D.books[f][s] || 0) > 0.0005));
    let h = `<table class="dtbl lv-tbl lv-five"><thead><tr><th>Holding</th>` + FUNDS.map(fundTh).join("") + `</tr></thead><tbody>`;
    D.classes.forEach((c) => {
      const mem = sleeves.filter((s) => D.class_of[s] === c);
      if (!mem.length) return;
      h += `<tr class="lv-grp2"><td class="strong">${c}</td>` + FUNDS.map((f) => {
        const t = mem.reduce((a, s) => a + (D.books[f][s] || 0), 0);
        return `<td class="num strong${selCol(f)}">${t > 0.0005 ? pct(t, 1) : "–"}</td>`;
      }).join("") + `</tr>`;
      mem.forEach((s) => {
        h += `<tr><td class="z" style="padding-left:1.2rem">${D.labels[s]}</td>` + FUNDS.map((f) => {
          const w = D.books[f][s] || 0;
          return `<td class="num${selCol(f)}">${w > 0.0005 ? pct(w, 1) : "<span class=\"z\">–</span>"}</td>`;
        }).join("") + `</tr>`;
      });
    });
    h += `<tr class="lv-grp2"><td class="strong">Horizon</td>` +
      FUNDS.map((f) => `<td class="num z${selCol(f)}">${D.funds[f].horizon}</td>`).join("") + `</tr>`;
    el("mandate-table").innerHTML = h + "</tbody></table>";
    bindHeads("mandate-table");
  }

  function factsTable() {
    el("facts-sub").textContent = `base currency ${F0.currency} · ${F0.pricing.toLowerCase()} · accumulating`;
    const rows = FUNDS.map((f) => {
      const x = D.facts[f];
      return `<tr class="lv-frow${f === fund ? " lv-me" : ""}" data-f="${f}"><td class="strong"><span class="lv-dot" style="--pc:${COLOR[f]}"></span>${f}</td>
        <td class="z">${x.role}</td><td>${x.reference}</td><td>${x.horizon}</td>
        <td>${x.managed === "active" ? "Actively run" : "Policy weights"}</td><td class="z">${x.dealing}</td></tr>`;
    }).join("");
    el("facts-table").innerHTML = `<table class="dtbl lv-tbl"><thead><tr><th>Portfolio</th><th>Role</th>
      <th>Reference</th><th>Horizon</th><th>Management</th><th>Dealing</th></tr></thead><tbody>${rows}</tbody></table>`;
    bindHeads("facts-table");
    el("facts-read").innerHTML =
      `All five carry the same terms: a <strong>${F0.fee_bps}bp</strong> annual fee accrued daily,
       <strong>${F0.dealing_bps}bp</strong> per side on anything dealt, and no single vehicle above
       <strong>${(F0.vehicle_cap * 100).toFixed(0)}%</strong> of a portfolio wherever the sleeve can be
       split across issuers (* Certain's single-vehicle T-bill sleeve runs at 26%, which the cap cannot
       bind). Income is reinvested — there is no distribution. There is deliberately <strong>no fund size,
       units in issue or ISIN</strong>: these are notional portfolios priced from market closes, and a
       subscription record they do not have is not something to invent.`;
  }

  function disclosure() {
    const items = [
      ["Past performance", `Past performance is not a guide to future performance. The record is
        ${T.months.toFixed(1)} months long — below the ${T.min_months_to_annualise} months at which a return
        is annualised and well below the ${T.min_months_for_risk_stats} at which risk statistics are
        normally quoted. <strong>No return on this page is annualised.</strong> Volatility and tracking
        error are annualised from daily observations, and the long-run backtest figures are stated per
        year — each is labelled where it appears.`],
      ["Two different things called performance", `The series on this page is the <strong>live</strong>
        NAV from ${fmtD(D.inception)}. The 1997–2026 figures elsewhere on the platform are a
        <strong>backtest of today's weights</strong> — a different basis, and they are not linked to or
        continued by this record.`],
      ["How the NAV is struck", `Daily, from dividend-adjusted closing prices of the vehicles actually
        held, in ${F0.currency}. A ${F0.fee_bps}bp annual fee accrues daily and ${F0.dealing_bps}bp per
        side is charged on anything dealt, including buying the book at launch. The whole series is
        recomputed from inception on every run, so a corrected price corrects the history rather than
        leaving a step in it.`],
      ["What this is not", `Not a custodial or audited record, not a price you could have dealt at, and
        not a fund you can buy. There is no fund size, no units in issue and no ISIN because there are
        no subscriptions — these are notional portfolios priced against the market.`],
      ["Data", `Vehicle prices from a public market-data feed (exploratory tier); the cash sleeve uses a
        FRED T-bill proxy; regime state from the Macro-Regime-Score platform. Priced to
        ${fmtD(D.asof)}.`]
    ];
    el("disclosure").innerHTML = `<div class="lv-disc">` + items.map(([h, b]) =>
      `<div class="vi"><div class="vi-l">${h}</div><div class="vi-v">${b}</div></div>`).join("") + `</div>`;
  }

  function status() {
    el("appbar-status").textContent = "Live · priced to " + fmtD(D.asof);
    el("status-footer").textContent =
      "NAV from Src/fund_nav.py · books from Src/pc_fs6_build.py · priced to " + fmtD(D.asof)
      + " · not a custodial record";
  }

  // ---------- notes ----------
  // The reasoning under each card stays on the page but collapses to two lines with a toggle, so
  // the numbers lead and the explanation is one click away rather than a wall of prose.
  function notes() {
    document.querySelectorAll("main .read").forEach((p) => {
      let btn = p.nextElementSibling && p.nextElementSibling.classList.contains("lv-more") ? p.nextElementSibling : null;
      p.classList.add("lv-clamp");
      const open = p.classList.contains("open");
      p.classList.remove("open");
      const long = p.scrollHeight > p.clientHeight + 2;
      if (open) p.classList.add("open");
      if (!long) { if (btn) btn.remove(); return; }
      if (!btn) {
        btn = document.createElement("button"); btn.className = "lv-more"; btn.type = "button";
        btn.onclick = () => { p.classList.toggle("open"); const o = p.classList.contains("open");
          btn.textContent = o ? "Show less" : "Read more"; btn.setAttribute("aria-expanded", String(o)); };
        p.insertAdjacentElement("afterend", btn);
      }
      btn.textContent = p.classList.contains("open") ? "Show less" : "Read more";
      btn.setAttribute("aria-expanded", String(p.classList.contains("open")));
    });
  }

  // ---------- layout: charts take the height their neighbour needs ----------
  // A chart beside a long table or a taller tile otherwise leaves a block of empty panel under it.
  function fitChart(id, target, min, max) {
    const c = el(id);
    if (!c || !target || window.innerWidth <= 1100) return;
    const cur = c.offsetHeight, h = Math.round(Math.max(min, Math.min(max, target)));
    if (Math.abs(h - cur) > 6) { c.style.height = h + "px"; Plotly.relayout(c, { height: h }); }
  }
  function fitAll() {
    // NAV chart grows to the height of the range-position tile beside it.
    const nav = el("nav-chart"), navTile = nav && nav.closest(".tile"), side = navTile && navTile.nextElementSibling;
    if (side) fitChart("nav-chart", nav.offsetHeight + side.offsetHeight - navTile.offsetHeight, 400, 640);
    // Attribution charts match the table they sit beside.
    // ...but bar thickness stays constant: a taller chart gets wider gaps, not fatter bars.
    ["bridge", "fac"].forEach((k) => {
      const t = el(k + "-table"), c = el(k + "-chart");
      if (t) fitChart(k + "-chart", t.offsetHeight, 340, 900);
      if (c && c.data && c.data[0]) {
        const rows = (c.data[0].y || []).length || 1;
        const band = (c.offsetHeight - 40) / rows;
        const gap = Math.max(0.25, Math.min(0.72, 1 - 22 / band));
        Plotly.relayout(c, { bargap: gap });
      }
    });
  }
  let fitT;
  window.addEventListener("resize", () => { clearTimeout(fitT); fitT = setTimeout(() => { notes(); fitAll(); }, 150); });

  // ---------- orchestration ----------
  // Each panel runs independently. They were once one statement: when one threw, every panel after it
  // silently did not render and the page still reported clean. A failure now names itself in the
  // footer and the rest of the page still renders.
  const PRODUCT = [["switcher", switcher], ["hero", hero], ["key facts", keyFacts], ["nav chart controls", navControls],
    ["NAV chart", navChart], ["range position", posMeters], ["returns", retTable], ["risk", riskPanel],
    ["month by month", monthPanel], ["holdings", holdTable], ["exposure", exposurePanel],
    ["dealing", dealingPanel], ["holdings bridge", bridgePanel], ["exposure attribution", facPanel]];
  const RANGE_SEL = [["range chart", rangeChart], ["characteristics", charsTable], ["discrete returns", perfTable],
    ["monthly", monthlyTable], ["mandates", mandateTable], ["terms", factsTable]];
  const ONCE = [["status", status], ["insight", insight], ["range controls", rangeControls], ["disclosure", disclosure]];

  function run(list, broke) {
    list.forEach(([name, fn]) => { try { fn(); } catch (e) { if (broke) broke.push(name); console.error("[live] " + name + ":", e); } });
  }
  function renderProduct() { run(PRODUCT); syncNav(); try { notes(); fitAll(); } catch (e) { console.error(e); } }
  function renderRangeSelection() { run(RANGE_SEL); try { notes(); } catch (e) { console.error(e); } }

  const broke = [];
  run(ONCE, broke); run(PRODUCT, broke); run(RANGE_SEL, broke); syncNav();
  try { notes(); fitAll(); } catch (e) { console.error("[live] layout:", e); }
  if (broke.length && el("status-footer")) {
    el("status-footer").textContent =
      `Error: ${broke.length} panel(s) failed to render — ${broke.join(", ")}.`;
  }
})();
